/* Original REI landing composition. Existing learning and project routes remain intact. */
window.REIDreamHome=()=>{
 const arrow='<span aria-hidden="true">↗</span>';
 const spaces=[['01','Research studio','Follow the evidence.','Build a library, capture passages, and connect your findings to a proposal.','research','Sources · Evidence · Claims'],['02','Research academy','Give curiosity direction.','Nine practical milestones. Learn a concept, explore an example, and write something of your own.','academy','Learn · Explore · Write'],['03','Your workspace','Keep every spark.','A place for loose ideas, working drafts, and the questions you keep coming back to.','notebook','Notes · Drafts · Reflection']];
 return `<div class="dream-home"><section class="dream-hero" aria-labelledby="dream-title"><div class="dream-hero-meta"><span><i></i> AN INDEPENDENT SPACE FOR CURIOUS MINDS</span><span>RESEARCH, CONNECTED. / 01</span></div><div class="dream-hero-copy"><h1 id="dream-title" aria-label="Curiosity. In a new dimension."><span>Curiosity.</span><span class="dream-outline">In a new</span><span>dimension.</span></h1><div class="dream-intro"><p>Let a question become something extraordinary. A living space to learn, connect evidence, and shape what comes next.</p><a class="button dream-cta" href="#research">Enter your research studio ${arrow}</a><a class="dream-text-link" href="#academy">Start with the fundamentals <span aria-hidden="true">→</span></a><div class="dream-lens-controls" aria-label="3D magnifying glass controls"><button type="button" data-lens-action="rotate">Rotate ↻</button><button type="button" data-lens-action="inspect" aria-pressed="false">Inspect +</button><button type="button" data-lens-action="reset">Reset</button></div></div></div><div class="dream-art" data-dream-scene aria-hidden="true"><div class="dream-fallback"><i></i><i></i><i></i></div><canvas></canvas><div class="dream-art-coordinate">LENS 001 / CONNECTING IDEAS</div></div><div class="dream-hero-bottom"><button class="dream-scroll" type="button" data-dream-scroll="observatory"><span class="dream-scroll-line" aria-hidden="true"></span>SCROLL TO DISCOVER</button><span>YOUR IDEAS. YOUR EVIDENCE. YOUR NEXT CHAPTER.</span><span class="dream-live"><i></i> MADE FOR EXPLORATION</span></div></section><section class="dream-manifesto" id="dream-manifesto"><div class="dream-section-top"><span>01 / THE POSSIBILITY</span><span>A LITTLE STRUCTURE. A LOT OF POSSIBILITY.</span></div><h2 data-dream-reveal>Big ideas start<br>with <span class="dream-silver">small questions.</span></h2><div class="dream-manifesto-bottom"><div class="dream-orbit-symbol" aria-hidden="true"><i></i><i></i><i></i></div><p>You don’t need all the answers to begin. Gather what matters. See a connection. Follow a different thread. REI gives your thinking room to evolve.</p><a href="#journey" class="dream-circle-link" aria-label="Explore your research journey">${arrow}</a></div></section><section class="dream-spaces" aria-labelledby="dream-spaces-title"><div class="dream-section-top"><span>02 / CONNECTED SPACES</span><span>ONE PLACE. MANY WAYS FORWARD.</span></div><h2 id="dream-spaces-title" data-dream-reveal>Make room<br>for your <span class="dream-silver">next idea.</span></h2>${spaces.map(([n,title,headline,desc,href,meta])=>`<a class="dream-space-row" href="#${href}" data-dream-reveal><span class="dream-space-index">${n}</span><div class="dream-space-art sculpture" data-sculpture="${90+Number(n)}" aria-hidden="true"><img class="sculpture-fallback" src="particle-fallback.svg" alt=""><canvas></canvas></div><div class="dream-space-copy"><span class="eyebrow">${title}</span><h3>${headline}</h3><p>${desc}</p><small>${meta}</small></div><span class="dream-space-arrow" aria-hidden="true">↗</span></a>`).join('')}</section><section class="dream-tools"><div class="dream-section-top"><span>03 / IDEAS INTO PRACTICE</span><span>FROM THE FIRST NOTE TO THE FINAL REVIEW.</span></div><div class="dream-tools-layout"><h2 data-dream-reveal>Less blank page.<br><span class="dream-silver">More possibility.</span></h2><div class="dream-tools-links"><a href="#toolkit"><span>01</span><div><h3>A toolkit for the process.</h3><p>Templates, guides, and checklists for your next step.</p></div>${arrow}</a><a href="#seminars"><span>02</span><div><h3>Make time to go deeper.</h3><p>Focused workshops to move your thinking forward.</p></div>${arrow}</a><a href="#notebook/readiness"><span>03</span><div><h3>See what’s taking shape.</h3><p>Review your proposal and decide what needs attention.</p></div>${arrow}</a></div></div></section><section class="dream-finale"><span class="eyebrow">A QUESTION IS ONLY THE BEGINNING.</span><h2 data-dream-reveal>What will<br>you <span class="dream-silver">discover?</span></h2><a href="#lesson/${nextLesson()}" class="button dream-cta">${state.completed.length?'Continue your journey':'Begin your journey'} ${arrow}</a><p>Your work stays on this device. No account required.</p><div class="dream-finale-word" aria-hidden="true">rei</div></section></div>`;
};
